ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(txt_Motivo_DNCG.Text),
    Notify(
        "Debe indicar el motivo del rechazo",
        NotificationType.Error
    ),
    IsBlank(
        LookUp(
            Solicitud_Compras,
            soli_num = txt_Num_Soli_DSG.Text
        )
    ) && IsBlank(
        LookUp(
            Compras_NoMarcadas,
            NSolicitud = txt_Num_Soli_DSG.Text
        )
    ),
    ForAll(
        Filter(
            glr_Detalles_DSG.AllItems,
            Checkbox3_2.Value = false
        ),
        Collect(
            Compras_NoMarcadas,
            {
                NSolicitud: Upper(txt_Num_Soli_DSG.Text),
                NFilaSolicitud: ThisRecord.req_line,
                Enviado: 0,
                Tipo_Envio: varEmpleado.Codigo,
                Motivo: txt_Motivo_DNCG.Text
            }
        )
    );
    RemoveIf(
        Compras_NoMarcadas,
        NSolicitud = txt_Num_Soli_DSG.Text && NFilaSolicitud in Filter(
            glr_Detalles_DSG.AllItems,
            Checkbox3_2.Value = true
        ).req_line && Enviado = 1 && Tipo_Envio = varEmpleado.Codigo
    );
    Collect(
        Solicitud_Compras,
        {
            soli_num: Upper(txt_Num_Soli_DSG.Text),
            fecha: DateValue(txt_Fecha_DSG.Text),
            solicitante: txt_Solicitante_DSG.Text,
            user: txt_User_DSG.Text,
            total: Value(txt_Total_DSG.Text),
            estado: "Gerencia"
        }
    );
    Back();
    Reset(txt_Num_Soli_DSG);
    UpdateContext({showContainer: false});
    Reset(txt_Motivo_DNCG)
);
